import {reviewDispatchEmail} from './email-review.mjs';
import {deploymentPath} from '../../deployment.mjs';
const labels={due:'Due',upcoming:'Upcoming',sent:'Completed via Apparition email · Provider accepted',handled:'Handled externally',skipped:'Skipped',failed:'Failed · Review required',unknown:'Outcome uncertain · Review required',claimed:'Claimed · Review required',blocked:'Unavailable · Review required'};
export const ukDay=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
export const aftercareDate=value=>value?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',day:'numeric',month:'short',year:'numeric'}).format(new Date(/^\d{4}-\d{2}-\d{2}$/.test(value)?value+'T12:00:00Z':value)):'Not recorded';
export function aftercareRows(rows,filter='due',search='',now=new Date()){
 const q=search.trim().toLowerCase();return rows.filter(r=>(filter==='all'||filter==='completed'&&['sent','handled'].includes(r.state)||filter==='skipped'&&r.state==='skipped'||filter==='upcoming'&&r.state==='upcoming'||filter==='due'&&(r.state==='due'||['failed','unknown','claimed'].includes(r.state)&&r.dueDate<=ukDay(now)))&&[r.reference,r.customerName,r.channel].join(' ').toLowerCase().includes(q)).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')||a.reference.localeCompare(b.reference));
}
const element=(document,tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
export function renderAftercareQueue(rows,{document=globalThis.document,root}={}){
 const el=(tag,text,cls)=>element(document,tag,text,cls);root.replaceChildren();root.append(el('h2','Customer Aftercare'),el('p','Personal follow-ups, seven calendar days after recorded dispatch. Due dates are reminders; no messages are sent automatically.','storage-note'));
 const filters=el('div',undefined,'admin-filters'),label=el('label','Show'),select=el('select');select.setAttribute('aria-label','Aftercare queue');for(const [value,title] of [['due','Due now'],['upcoming','Upcoming'],['completed','Completed'],['skipped','Skipped'],['all','All']]){const o=el('option',title);o.value=value;select.append(o);}select.value=root.dataset.filter||'due';label.append(select);
 const searchLabel=el('label','Search aftercare'),search=el('input');search.type='search';search.value=root.dataset.search||'';search.placeholder='Order, customer or channel';searchLabel.append(search);filters.append(label,searchLabel);root.append(filters);
 const scroll=el('div',undefined,'admin-table-scroll');scroll.tabIndex=0;scroll.setAttribute('role','region');scroll.setAttribute('aria-label','Customer aftercare records');const table=el('table'),caption=el('caption','Customer aftercare reminders','sr-only'),head=el('thead'),headRow=el('tr');for(const title of ['Order','Customer','Channel','Dispatched','Follow-up due','Shipping','Tracking','State','Action'])headRow.append(el('th',title));head.append(headRow);const body=el('tbody'),empty=el('p','No aftercare reminders in this view.');table.append(caption,head,body);scroll.append(table);root.append(scroll,empty);
 function draw(){root.dataset.filter=select.value;root.dataset.search=search.value;body.replaceChildren();const filtered=aftercareRows(rows,select.value,search.value);empty.hidden=filtered.length>0;for(const r of filtered){const tr=el('tr'),ref=el('td'),link=el('a',r.reference);link.href=deploymentPath('/admin/orders/?id='+encodeURIComponent(r.orderId));ref.append(link);tr.append(ref,...[r.customerName||'Not supplied',r.channel,aftercareDate(r.dispatchAt),aftercareDate(r.dueDate),r.shippingService||'Not recorded',r.tracking,labels[r.state]||r.state].map(v=>el('td',v)));const action=el('td'),open=el('a',r.state==='due'?'Review follow-up':'Open order','button');open.href=link.href;action.append(open);tr.append(action);body.append(tr);}}
 select.addEventListener('change',draw);search.addEventListener('input',draw);draw();
}
export function aftercareActionDialog(row,action,{document=globalThis.document}={}){
 return new Promise(resolve=>{const el=(tag,text,cls)=>element(document,tag,text,cls),previous=document.activeElement,dialog=el('dialog',undefined,'external-dispatch-dialog aftercare-action-dialog'),title=el('h2',({reschedule:'Reschedule aftercare',handled:'Mark aftercare as handled',skip:'Skip aftercare',suppress:'Record no-aftercare contact preference'})[action]);title.id='aftercare-action-title';dialog.setAttribute('aria-labelledby',title.id);const form=el('form'),reasonLabel=el('label','Reason / outcome (required, 5–1000 characters)'),reason=el('textarea');reason.required=true;reason.minLength=5;reason.maxLength=1000;reasonLabel.append(reason);let due=null;if(action==='reschedule'){const label=el('label','Follow-up date (UK calendar date)');due=el('input');due.type='date';due.required=true;due.value=row.dueDate;due.min=ukDay(row.dispatchAt);due.max='2100-12-31';label.append(due);form.append(label);}
 let confirmed=null;if(action==='handled'||action==='suppress'){const label=el('label',undefined,'email-review-recipient');confirmed=el('input');confirmed.type='checkbox';confirmed.required=true;label.append(confirmed,document.createTextNode(action==='handled'?' I confirm I have handled this follow-up through the appropriate order communication route.':' The customer requested no aftercare email. Apply this preference to the saved recipient across orders.'));form.append(label);}
 const note=el('p',action==='handled'?'This records external handling, not provider delivery.':action==='suppress'?'This skips this reminder and suppresses optional aftercare email for this saved recipient. Essential order updates are unaffected. Recipient: '+(row.recipient||'Not recorded')+'.':'This changes the reminder only. It does not change fulfilment or send a message.'),actions=el('div',undefined,'dialog-actions'),cancel=el('button','Cancel','button'),save=el('button','Confirm','button');cancel.type='button';save.type='submit';save.disabled=true;actions.append(cancel,save);form.append(reasonLabel,note,actions);const enable=()=>save.disabled=reason.value.trim().length<5||reason.value.trim().length>1000||/[\x00-\x1f\x7f]/.test(reason.value)||!!confirmed&&!confirmed.checked||!!due&&(!due.value||due.value<due.min||due.value>due.max);form.addEventListener('input',enable);form.addEventListener('change',enable);
 let closed=false;const finish=result=>{if(closed)return;closed=true;dialog.close();dialog.remove();previous?.focus();resolve(result);};cancel.addEventListener('click',()=>finish(null));dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null);});form.addEventListener('submit',e=>{e.preventDefault();if(save.disabled)return;finish({reason:reason.value.trim(),dueDate:due?.value||null});});dialog.append(title,el('p',row.reference),form);document.body.append(dialog);dialog.showModal();cancel.focus();});
}
export function mountAftercarePanel(order,row,{document=globalThis.document,root,repository,refresh,message,review=reviewDispatchEmail,actionDialog=aftercareActionDialog}={}){
 const el=(tag,text,cls)=>element(document,tag,text,cls),section=el('section',undefined,'order-aftercare');section.append(el('h3','Customer Aftercare'));
 if(!row){section.append(el('p','Available after a valid recorded dispatch. No automatic follow-up is sent.','storage-note'));root.append(section);return;}
 section.append(el('p','Suggested follow-up: '+aftercareDate(row.defaultDue)),el('p','Current follow-up: '+aftercareDate(row.dueDate)+' · '+(labels[row.state]||row.state)));
 if(row.notice)section.append(el('p',row.notice,'storage-note'));
 const actions=el('div',undefined,'dialog-actions');let busy=false;
 function button(text,fn){const b=el('button',text,'button');b.type='button';b.addEventListener('click',async()=>{if(busy)return;busy=true;for(const n of actions.querySelectorAll('button'))n.disabled=true;try{await fn();}catch(e){message.textContent=e.message;}finally{busy=false;for(const n of actions.querySelectorAll('button'))n.disabled=false;}});actions.append(b);}
 if(row.eligible&&row.state==='due'&&!row.suppressed)button('Preview Thank-You',async()=>{const notice=await review(order,{document,kind:'aftercare'});await refresh();if(notice)message.textContent=notice;});
 if(row.eligible&&['due','upcoming','failed','unknown'].includes(row.state)){
  for(const [action,title] of [...(['due','upcoming'].includes(row.state)?[['reschedule','Reschedule']]:[]),['handled','Mark as Handled'],['skip','Skip'],...(['WEBSITE','DIRECT'].includes(row.channel)&&!row.suppressed?[['suppress','No Aftercare Email']]:[])])button(title,async()=>{const input=await actionDialog(row,action,{document});if(!input)return;await repository.updateAftercare(row.orderId,row,action,input);await refresh();message.textContent='Aftercare updated. No message was sent.';});
 }
 section.append(actions);
 if(row.history?.length){const details=el('details'),summary=el('summary','Aftercare actions');details.append(summary);for(const h of row.history)details.append(el('p',`${aftercareDate(h.at)} · ${h.action} · ${h.reason} · Admin ${h.actor}${h.toDue&&h.toDue!==h.fromDue?' · Due '+aftercareDate(h.toDue):''}`));section.append(details);}
 const deliveries=(order.emailDeliveries||[]).filter(d=>d.kind==='aftercare');if(deliveries.length){const audit=el('details');audit.append(el('summary','Aftercare notification audit'));for(const d of deliveries)audit.append(el('p',`${d.state==='sent'?'Provider accepted · Inbox delivery not confirmed':d.state+' · Review required'} · ${d.recipient_email||'Saved recipient'} · ${aftercareDate(d.sent_at||d.attempted_at||d.created_at)} · Operation ${d.operation_id||'Unavailable'}`));section.append(audit);}
 root.append(section);
}
